void pin(const live::FileIdentity& i){auto actual=live::observePinnedFile(i.path,i.sha256);need(actual.bytes==i.bytes,"active input size mismatch");}
std::string boundedPinnedGuess(const live::FileIdentity& file){need(file.bytes>0&&file.bytes<=512*1024,"bounded guess bytes");const int fd=::open(file.path.c_str(),O_RDONLY|O_NOFOLLOW|O_CLOEXEC);need(fd>=0,"guess nofollow readonly open");struct Close {int fd;~Close(){::close(fd);}} close{fd};struct stat st{};need(::fstat(fd,&st)==0&&S_ISREG(st.st_mode)&&st.st_size>=0&&static_cast<live::Count>(st.st_size)==file.bytes,"actual opened guess bounded identity size");std::string bytes(file.bytes,'\0');std::size_t n=0;while(n<bytes.size()){const auto k=::read(fd,bytes.data()+n,bytes.size()-n);if(k<0&&errno==EINTR)continue;need(k>0,"exact bounded guess read");n+=k;}char tail;ssize_t end;do{end=::read(fd,&tail,1);}while(end<0&&errno==EINTR);need(end==0,"guess grew beyond declared size");unsigned char digest[32];unsigned length=0;need(EVP_Digest(bytes.data(),bytes.size(),digest,&length,EVP_sha256(),nullptr)==1&&length==32,"opened guess byteSHA");std::string sha;const char* hex="0123456789abcdef";for(unsigned char b:digest){sha.push_back(hex[b>>4]);sha.push_back(hex[b&15]);}need(sha==file.sha256,"exact parsed guess bytes hash mismatch");return bytes;}
Eigen::Vector3d vec3(const YAML::Node& n){need(n.IsSequence()&&n.size()==3,"three-vector");return {n[0].as<double>(),n[1].as<double>(),n[2].as<double>()};}
bool bits(const std::vector<mjtNum>& a,const std::vector<mjtNum>& b){return a.size()==b.size()&&(a.empty()||std::memcmp(a.data(),b.data(),a.size()*sizeof(mjtNum))==0);}
