class DurableWarmupJournal final {int fd=-1;std::size_t bytes=0,events=0;std::string path;public:explicit DurableWarmupJournal(const std::string& file):path(file){fd=::open(file.c_str(),O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW|O_CLOEXEC,0600);need(fd>=0,"fresh durable warmup journal");}~DurableWarmupJournal(){if(fd>=0)::close(fd);}void append(const rt::WarmupPoint& p,const std::string& event){std::ostringstream o;o<<std::setprecision(17)<<event<<","<<p.substep<<","<<p.simulation_time<<","<<p.native_returned<<","<<p.native_joints_read<<","<<p.scratch_joints_read<<","<<p.contacts;for(int n:p.warnings)o<<","<<n;for(const auto* v:{&p.q,&p.v,&p.C,&p.acceleration,&p.jerk})for(double x:*v)o<<","<<x;o<<","<<p.jerk_available<<","<<p.geometry_complete<<","<<p.independent_observer_guard<<","<<p.minimum_true<<","<<p.minimum_cover<<","<<p.geometry_queries<<","<<p.tcp_frame_error<<","<<p.arm_frame_error<<"\n";const auto line=o.str();need(line.size()<=4096&&bytes+line.size()<=12582912,"bounded durable warmup journal");std::size_t n=0;while(n<line.size()){const auto k=::write(fd,line.data()+n,line.size()-n);if(k<0&&errno==EINTR)continue;need(k>0,"durable journal write prefix retained");n+=k;bytes+=k;}need(::fsync(fd)==0,"durable warmup journal fsync");++events;}void receipt(evidence::Evidence& out){need(::fsync(fd)==0,"journal final fsync");std::ifstream in(path,std::ios::binary);need(bool(in),"journal receipt open");std::unique_ptr<EVP_MD_CTX,decltype(&EVP_MD_CTX_free)> h(EVP_MD_CTX_new(),EVP_MD_CTX_free);need(h&&EVP_DigestInit_ex(h.get(),EVP_sha256(),nullptr)==1,"journal receipt hash init");char buffer[4096];std::size_t seen=0,newlines=0;char last=0;while(in){in.read(buffer,sizeof(buffer));const auto n=in.gcount();if(n>0){seen+=n;need(seen<=12582912&&EVP_DigestUpdate(h.get(),buffer,n)==1,"journal receipt bounded hash");for(int j=0;j<n;++j)if(buffer[j]=='\n')++newlines;last=buffer[n-1];}}need(in.eof(),"journal receipt complete read");unsigned char digest[32];unsigned n=0;need(EVP_DigestFinal_ex(h.get(),digest,&n)==1&&n==32,"journal final hash");std::string sha;const char* hex="0123456789abcdef";for(unsigned char b:digest){sha.push_back(hex[b>>4]);sha.push_back(hex[b&15]);}const auto pin=live::observePinnedFile(path,sha);need(pin.bytes==seen,"journal receipt stable size/hash");out.write("journal_receipt.bin","ACTUAL_DURABLE_WARMUP_JOURNAL_PREFIX_V2",[&](evidence::BinaryFile& f){f.text(path);f.text(sha);f.u64(seen);f.u64(bytes);f.u64(events);f.u64(newlines);f.u64(seen&&last!='\n');f.text("hard termination may leave final step-attempt without native-return: native entry/advancement UNKNOWN; retain exact complete newline prefix; binary128MiB plus separate journal12MiB caps");});}};
